import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,e as t}from"./app-bc94d2a9.js";const o={},e=t(`<h1 id="q-和-f-对象" tabindex="-1"><a class="header-anchor" href="#q-和-f-对象" aria-hidden="true">#</a> Q 和 F 对象</h1><p>在 Tortoise ORM 中，<code>Q</code> 和 <code>F</code> 对象用于<strong>构建复杂查询</strong>，类似于 Django ORM。</p><hr><h2 id="_1-q-对象" tabindex="-1"><a class="header-anchor" href="#_1-q-对象" aria-hidden="true">#</a> <strong>1. Q 对象</strong></h2><p><code>Q</code> 对象用于<strong>组合多个查询条件</strong>，支持 <strong>AND（&amp;）、OR（|）、NOT（~）</strong> 操作符。<br> 它用于 <strong>动态构建查询</strong>，特别是在有可选过滤条件的情况下。</p><h3 id="示例-q-对象的使用" tabindex="-1"><a class="header-anchor" href="#示例-q-对象的使用" aria-hidden="true">#</a> <strong>示例：Q 对象的使用</strong></h3><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> tortoise<span class="token punctuation">.</span>expressions <span class="token keyword">import</span> Q
<span class="token keyword">from</span> models <span class="token keyword">import</span> Book

<span class="token comment"># 查询 name=&quot;Python&quot; 或 price 大于 50 的书籍</span>
books <span class="token operator">=</span> <span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span>Q<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Python&quot;</span><span class="token punctuation">)</span> <span class="token operator">|</span> Q<span class="token punctuation">(</span>price__gt<span class="token operator">=</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token comment"># 查询 name=&quot;Python&quot; 且 price 小于 100 的书籍</span>
books <span class="token operator">=</span> <span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span>Q<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Python&quot;</span><span class="token punctuation">)</span> <span class="token operator">&amp;</span> Q<span class="token punctuation">(</span>price__lt<span class="token operator">=</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token comment"># 查询 price 不等于 50 的书籍</span>
books <span class="token operator">=</span> <span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span><span class="token operator">~</span>Q<span class="token punctuation">(</span>price<span class="token operator">=</span><span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>🔹 <strong>作用</strong>：</p><ul><li>允许 <strong>OR 条件</strong>（普通 <code>.filter(name=&quot;Python&quot;, price__gt=50)</code> 是 AND 关系）</li><li>允许 <strong>动态构建查询</strong>（可以根据条件是否存在来构造 <code>Q</code> 对象）</li></ul><hr><h2 id="_2-f-对象" tabindex="-1"><a class="header-anchor" href="#_2-f-对象" aria-hidden="true">#</a> <strong>2. F 对象</strong></h2><p><code>F</code> 对象用于<strong>引用数据库中的字段</strong>，主要用于<strong>字段间的比较或更新</strong>。</p><h3 id="示例-f-对象的使用" tabindex="-1"><a class="header-anchor" href="#示例-f-对象的使用" aria-hidden="true">#</a> <strong>示例：F 对象的使用</strong></h3><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> tortoise<span class="token punctuation">.</span>expressions <span class="token keyword">import</span> F
<span class="token keyword">from</span> models <span class="token keyword">import</span> Book

<span class="token comment"># 查询 price 大于 pages 数量的书籍</span>
books <span class="token operator">=</span> <span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span>price__gt<span class="token operator">=</span>F<span class="token punctuation">(</span><span class="token string">&quot;pages&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token comment"># 将所有书籍的 price 提高 10</span>
<span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>update<span class="token punctuation">(</span>price<span class="token operator">=</span>F<span class="token punctuation">(</span><span class="token string">&quot;price&quot;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">10</span><span class="token punctuation">)</span>

<span class="token comment"># 将 price 设为 pages 的 2 倍</span>
<span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>update<span class="token punctuation">(</span>price<span class="token operator">=</span>F<span class="token punctuation">(</span><span class="token string">&quot;pages&quot;</span><span class="token punctuation">)</span> <span class="token operator">*</span> <span class="token number">2</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>🔹 <strong>作用</strong>：</p><ul><li>允许<strong>字段之间的比较</strong>（如 <code>price &gt; pages</code>）</li><li>允许<strong>数据库内的字段更新</strong>（如 <code>price = price + 10</code>）</li><li>避免查询后再更新，提升<strong>数据库性能</strong>（直接在 SQL 层执行）</li></ul><hr><h2 id="_3-q-f-组合使用" tabindex="-1"><a class="header-anchor" href="#_3-q-f-组合使用" aria-hidden="true">#</a> <strong>3. Q + F 组合使用</strong></h2><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 查询 price 大于 pages 并且 name 以 &quot;Python&quot; 开头的书籍</span>
books <span class="token operator">=</span> <span class="token keyword">await</span> Book<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span>Q<span class="token punctuation">(</span>price__gt<span class="token operator">=</span>F<span class="token punctuation">(</span><span class="token string">&quot;pages&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">&amp;</span> Q<span class="token punctuation">(</span>name__startswith<span class="token operator">=</span><span class="token string">&quot;Python&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> <strong>总结</strong></h2><table><thead><tr><th>对象</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>Q</code></td><td><strong>构造复杂查询</strong>（支持 <code>&amp;</code>、\`</td><td><code>、</code>~\`）</td></tr><tr><td><code>F</code></td><td><strong>引用字段</strong>（用于字段间比较或更新）</td><td><code>Book.filter(price__gt=F(&quot;pages&quot;))</code></td></tr></tbody></table><p><strong>什么时候用？</strong></p><ul><li><strong>Q</strong>：用于 <strong>动态构建查询</strong>，比如用户可选多个筛选条件时。</li><li><strong>F</strong>：用于 <strong>字段计算</strong>，比如 <strong>批量更新</strong> 时直接在数据库操作，提升性能。</li></ul><p>你是要用 <code>Q</code> 和 <code>F</code> 来优化什么查询吗？😊</p>`,25),p=[e];function c(r,i){return s(),a("div",null,p)}const d=n(o,[["render",c],["__file","QandF.html.vue"]]);export{d as default};
